def eh_palindromo(texto):
    esq = 0
    dir = len(texto) - 1
    while esq < dir:
        if texto[esq] != texto[dir]:
            return False
        esq += 1
        dir -= 1
    return True

print(eh_palindromo('radar'))  # True

